@extends('layouts.app') @section('heading','Scan Barcode') @section('subheading','Arahkan kamera ke QR kartu siswa') @push('head')<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script>@endpush @section('content')<div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><div class="d-flex justify-content-between mb-3"><span class="badge bg-success-subtle text-success" id="camStatus">Menyiapkan kamera...</span><strong id="clock"></strong></div><div id="reader"></div><div id="scanResult" class="alert mt-3 d-none"></div></div></div></div><div class="col-lg-5"><div class="stat-card mb-3"><div class="stat-icon bg-primary-subtle text-primary"><i class="bi bi-check2-all"></i></div><div><small>Tercatat Hari Ini</small><h3 id="todayCount">{{$today}}</h3></div></div><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Aktivitas Terbaru</div><div class="list-group list-group-flush" id="activity"><div class="empty">Belum ada hasil scan.</div></div></div></div></div>@endsection @push('scripts')<script>const result=document.getElementById('scanResult');let locked=false;function clock(){document.getElementById('clock').textContent=new Date().toLocaleString('id-ID')}setInterval(clock,1000);clock();function scanned(token){if(locked)return;locked=true;fetch('{{route('attendance.scan.store')}}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({token})}).then(async r=>{let d=await r.json();if(!r.ok)throw new Error(d.message||Object.values(d.errors||{})[0]?.[0]);let a=d.attendance;result.className='alert alert-success mt-3';result.textContent=`Berhasil: ${a.student.name}, Kelas ${a.student.school_class.class_name}, ${a.status} pukul ${a.check_in_time}.`;document.getElementById('todayCount').textContent=+document.getElementById('todayCount').textContent+1;document.getElementById('activity').insertAdjacentHTML('afterbegin',`<div class="list-group-item"><strong>${a.student.name}</strong><br><small>${a.status} · ${a.check_in_time}</small></div>`);new Audio('data:audio/wav;base64,UklGRnoGAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQoG').play().catch(()=>{});}).catch(e=>{result.className='alert alert-danger mt-3';result.textContent=e.message||'Scan gagal.'}).finally(()=>setTimeout(()=>locked=false,2500))}const qr=new Html5QrcodeScanner('reader',{fps:10,qrbox:{width:230,height:230},rememberLastUsedCamera:true},false);qr.render(scanned,()=>{});document.getElementById('camStatus').textContent='Kamera siap';</script>@endpush
